{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_15",
      "quote": "We included randomised trials in people with suspected, probable, or confirmed covid-19 that compared blood products and covid-19-specific antiviral antibodies against one another or against no intervention, placebo, or standard care. We included trials regardless of publication status (peer reviewed, in press, or preprint) or language. No restrictions were applied based on severity of illness or setting. For each eligible trial, pairs of reviewers, following training and calibration exercises, extract data independently using a standardised, pilot tested data extraction form. Reviewers collect information on trial characteristics (trial registration, publication status, study status, design), patient characteristics (country, age, sex, smoking habits, comorbidities, setting and type of care, severity of covid-19 symptoms, timing of therapy relative to symptom onset), donor characteristics (selection criteria, sex, severity of disease), and outcomes of interest (means or medians and measures of variability for continuous outcomes and the number of participants analysed and the number of participants who experienced an event for dichotomous outcomes). We excluded randomised trials evaluating vaccines, pharmacologic drugs, nutrition, traditional Chinese herbal medicines, and non-drug supportive care interventions. We identified and separately categorised trials including patients with covid-19 that evaluated these interventions. Randomised trials evaluating drug treatments and prophylaxis for covid-19 were synthesised in separate living network meta-analyses. We excluded non-randomised trials.",
      "reason": "Explicit specification of population (suspected/probable/confirmed), eligible study design (randomised trials), interventions and comparators, exclusions (vaccines, drugs, non-randomised trials), settings/severity (no restrictions), and many trial/patient/donor characteristics used to determine eligibility."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_15",
      "quote": "We included trials regardless of publication status (peer reviewed, in press, or preprint) or language.",
      "reason": "The review specifies publication/report status and language eligibility but does not state any dissemination year restrictions; thus report-characteristic criteria are partially specified."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit statement distinguishing exclusion because outcomes were not measured from exclusion because outcome results were not reported is present in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_20",
      "quote": "We performed bayesian random-effects network meta-analysis for outcomes with sufficient data, and synthesise all other outcomes using pairwise bayesian random-effects meta-analyses if there was only one comparison for a specific outcome.",
      "reason": "The methods state which synthesis methods will be used (network or pairwise) and text_15 defines the comparisons (blood products and antiviral antibodies versus each other or versus no intervention/placebo/standard care), but the evidence does not explicitly map each named group to the specific syntheses or link every synthesis grouping to the review objectives in a detailed way."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "callout_0",
      "quote": "We utilised a comprehensive literature search without any restrictions on language or publication status, explicit eligibility criteria, and limited meta-analysis of interventions that were randomised to at least 100 patients (or had \u226520 events) to avoid spurious or imprecise findings with network meta-analysis.",
      "reason": "Provides a rationale for a notable restriction (threshold for conducting meta-analysis: ≥100 patients or ≥20 events) explaining it was to avoid spurious or imprecise findings."
    }
  ],
  "confidence": "80"
}

