    {
      "element_id": "prisma_2020_6_e6",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "There is no description of types of individuals (eg, authors, experts) contacted to identify studies."
    },
    {
      "element_id": "prisma_2020_6_e7",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not specify the types of reference lists examined (eg, reference lists of included studies or relevant reviews)."
    },
    {
      "element_id": "prisma_2020_6_e8",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No information is provided on backward or forward citation searching (seed reports, citation index/platform, or search dates)."
    },
    {
      "element_id": "prisma_2020_6_e9",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not report consulting journals or conference proceedings as separate sources, and provides no information on names, dates covered, or search methods for such sources; evidence does not indicate this requirement applies."
    }
  ],
  "confidence": "85"
