    {
      "element_id": "prisma_2020_7_e3",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": "We adapted the search terms for covid-19 developed by the CDC to the Chinese language.",
      "reason": "A published search approach (CDC search terms) is cited and the adaptation to Chinese is explicitly described."
    },
    {
      "element_id": "prisma_2020_7_e4",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": "To identify randomised controlled trials, we filter the results from the WHO database through a validated and highly sensitive machine learning model.",
      "reason": "The manuscript specifies use of a machine learning model (a text-analysis tool) to filter search results for randomized controlled trials."
    },
    {
      "element_id": "prisma_2020_7_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No information is provided in the supplied evidence about tools used to translate search strings between sources."
    },
    {
      "element_id": "prisma_2020_7_e6",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The supplied evidence does not describe any validation of the overall search strategy, its validation process, or validation studies (aside from a mention of a validated ML filter for RCT identification, which is not validation of the search strategy itself)."
    },
    {
      "element_id": "prisma_2020_7_e7",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "There is no description in the supplied evidence of any peer review of the search strategy or use of tools such as PRESS."
    },
    {
      "element_id": "prisma_2020_7_e8",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The supplied evidence does not state that the search structure was not based on PICO nor describe any alternative conceptual structure or explorations."
    }
  ],
  "confidence": 70
}

